const raw = $input.first().json.output[0].content[0].text;

// Remove markdown code blocks if present
const cleaned = raw.replace(/```json|```/g, '').trim();

let parsedData;

try {
  parsedData = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Failed to parse JSON: ${error.message}\nRaw output: ${raw}`);
}

return [{ json: parsedData }];

const msg = $input.first().json.message;

return [{
  json: {
    chat_id: msg.chat.id,
    text: msg.text,
    username: msg.from.username || msg.from.first_name
  }
}];

const chatId = $node["Telegram Trigger"].json.message.chat.id;

// get all rows
const rows = $input.all();

// filter rows belonging to this user
const userRows = rows.filter(r => r.json.chat_id == chatId);

// get last appended row for that user
const lastRow = userRows[userRows.length - 1];

return [{
  json: {
    state: lastRow.json.state,
    row_number: lastRow.json.row_number,
    chat_id: lastRow.json.chat_id
  }
}];

const items = $input.all();

// get the current user chat_id
const chatId = $('extract').first().json.chat_id;

// filter rows for this user and collect stocks
const stocks = items
  .filter(item => item.json.chat_id == chatId && item.json.stock)
  .map(item => item.json.stock);

// return all stocks for that chat_id
return [{
  json: {
    chat_id: chatId,
    stocks: stocks
  }
}];

// get all rows from Google Sheets
const items = $input.all();

// stock entered by user
const newStock = $('extract').first().json.text.trim().toLowerCase();

// current user
const chatId = $('extract').first().json.chat_id;

// get existing stocks array
const existingStocks = $input.first().json.stocks || [];

// convert all existing stocks to lowercase
const normalizedStocks = existingStocks.map(stock => stock.toLowerCase());

// check if the new stock already exists
const exists = normalizedStocks.includes(newStock);

if (exists) {
  return [{
    json: {
      allowAdd: false,
      chat_id: chatId,
      message: `⚠️ ${newStock.toUpperCase()} is already in your portfolio.`
    }
  }];
}

// allow stock to be added
return [{
  json: {
    allowAdd: true,
    chat_id: chatId,
    stock: newStock.toUpperCase()
  }
}];

