// rows from Google Sheets (used to get row_number)
const items = $items("Get row(s) in sheet3");

// stock entered by user
const stockToRemove = $('extract').first().json.text.trim().toLowerCase();

// current user
const chatId = $('extract').first().json.chat_id;

// existing stocks array
const existingStocks = $input.first().json.stocks || [];

// convert all stocks to lowercase
const normalizedStocks = existingStocks.map(s => s.toLowerCase());

// check if stock exists
const exists = normalizedStocks.includes(stockToRemove);

// find row in Google Sheet
const match = items.find(item =>
  item.json.chat_id == chatId &&
  item.json.stock &&
  item.json.stock.toLowerCase() === stockToRemove
);

// if stock not found
if (!exists || !match) {
  return [{
    json: {
      found: false,
      chat_id: chatId,
      message: `⚠️ ${stockToRemove.toUpperCase()} is not in your portfolio.`
    }
  }];
}

// if stock found
return [{
  json: {
    found: true,
    chat_id: chatId,
    stock: stockToRemove.toUpperCase(),
    row_number: match.json.row_number,
    message: `✅ ${stockToRemove.toUpperCase()} found in your portfolio. Removing it now.`
  }
}];

const items = $input.all();

// chat_id of the user asking for the portfolio
const chatId = $('extract').first().json.chat_id;

// filter only rows belonging to this user
const stocks = items
  .filter(item => item.json.chat_id == chatId && item.json.stock)
  .map(item => item.json.stock);

// if no stocks exist
if (stocks.length === 0) {
  return [{
    json: {
      chat_id: chatId,
      message: "📊 Your portfolio is currently empty."
    }
  }];
}

// return the portfolio message
return [{
  json: {
    chat_id: chatId,
    message: "📊 Your Portfolio:\n\n• " + stocks.join("\n• ")
  }
}];

